Section CX.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x1 x5 x6 x7 x10 x11 x13 x15 x16 x22 x23 x26 x27 x29 : word).
  Variables (m : fmem) (DT SY b e tb tl sym1 : Z) (sorted : list (option Z)) (js jt : list byte) (ncells : nat).
  Variable POST : machine_state -> Prop.
  Hypothesis HJT : length jt = (4 * ncells)%nat.
  Hypothesis HJS : length js = length sorted.
  Hypothesis HLS : length sorted = 256%nat.
  Hypothesis HSYR : forall i v, nth i sorted None = Some v -> 0 <= v < 256.
  Hypothesis HDT : 0 < DT /\ DT + 4 + 4 * Z.of_nat ncells <= 2^47.
  Hypothesis DJ : DT + 4 + 4 * Z.of_nat ncells <= SY \/ SY + 256 <= DT + 4.
  Hypothesis HSY : 0 < SY /\ SY + 256 <= 2^47.
  Hypothesis HTB : 1 <= tb <= 12.
  Hypothesis HTL : tl - tb = 0.
  Hypothesis HS1 : 0 <= sym1 < 256.
  Hypothesis HBE : 0 <= b <= e /\ e <= 256.
  Notation INV m1 dt := (x2f_inv m m1 DT SY js jt sorted ncells dt).
  Notation D2 := (sym1 + tb * 65536 + 33554432).

  Lemma c2a_inner : forall f s dt u m1 r (x9 x21 x25 : word),
    fill_for_weight f dt u s e tb tl sym1 2 sorted = Ok r ->
    Z.of_nat f = e - s + 1 -> b <= s < e -> 0 <= u -> INV m1 dt ->
    (forall m2 dt' (y8 y9 y14 y17 y21 y25 : word),
       r = (dt', u + 1 * (e - s)) -> INV m2 dt' ->
       evt psegs POST (MS (mkR x1 sp gp tp x5 x6 x7 y8 y9 x10 x11 (Z_to_bv 64 (Z.lor sym1 33554432)) x13 y14 x15 x16 y17
                               (Z_to_bv 64 2) (Z_to_bv 64 4) (Z_to_bv 64 8) y21 x22 x23 (Z_to_bv 64 SY) y25 x26 x27
                               (Z_to_bv 64 D2) x29 (Z_to_bv 64 1) (Z_to_bv 64 3))
                          F (Z_to_bv 64 0x140c4) fc None m2 (seg_rom psegs))) ->
    evt psegs POST (MS (mkR x1 sp gp tp x5 x6 x7 (Z_to_bv 64 (e - s)) x9 x10 x11 (Z_to_bv 64 (Z.lor sym1 33554432)) x13
                            (Z_to_bv 64 (DT + 4 + 4 * u)) x15 x16 (Z_to_bv 64 (SY + s)) (Z_to_bv 64 2) (Z_to_bv 64 4)
                            (Z_to_bv 64 8) x21 x22 x23 (Z_to_bv 64 SY) x25 x26 x27 (Z_to_bv 64 D2) x29
                            (Z_to_bv 64 1) (Z_to_bv 64 3))
                       F (Z_to_bv 64 0x1428c) fc None m1 (seg_rom psegs)).
